SXF.ntube = function(o){ o = o || {}; const R = (k, inner) => sxR(o, k, inner);
  let s = `<svg class="sxntube sxbody" viewBox="0 0 420 444" width="420" role="img" aria-label="${esc(u('e6t'))}"><ellipse class="skin" cx="210" cy="226" rx="108" ry="200"/>`;
  s += R('anp', `<path class="hit" d="M170 40h80v100h-80z"/><path class="ntf" d="M198 132C190 100 176 70 168 44M222 132C230 100 244 70 252 44"/><path class="ntopen" d="M198 132C190 100 176 70 168 44L252 44C244 70 230 100 222 132Z"/>`);
  s += R('pnp', `<path class="hit" d="M176 318h68v96h-68z"/><path class="ntf" d="M198 322C192 352 182 382 178 408M222 322C228 352 238 382 242 408"/><path class="ntopen" d="M198 322C192 352 182 382 178 408L242 408C238 382 228 352 222 322Z"/>`);
  s += R('nt', `<rect class="nttube" x="198" y="130" width="24" height="194" rx="10"/><line class="ntgroove" x1="210" y1="138" x2="210" y2="316"/>`);
  let so = ''; for (let y = 146; y <= 300; y += 22){ so += `<rect class="ntsom" x="160" y="${y}" width="26" height="16" rx="5"/><rect class="ntsom" x="234" y="${y}" width="26" height="16" rx="5"/>`; }
  s += R('som', `<path class="hit" d="M156 140h34v180h-34zM230 140h34v180h-34z"/>${so}`);
  s += R('nc', `<path class="hit" d="M188 134h8v188h-8zM224 134h8v188h-8z"/><line class="ntnc" x1="193" y1="138" x2="193" y2="318"/><line class="ntnc" x1="227" y1="138" x2="227" y2="318"/>`);
  Object.keys(NTN).forEach(k => { if (!sxShow(o, k)) return; const p = NTN[k][1]; s += `<text class="sxl" x="${p[0]}" y="${p[1]}" text-anchor="${p[2]}">${esc(T(NTN[k][0]))}</text>`; });
  return s + `</svg>`; };
